import Typesense from 'typesense';
import fs from 'fs';

const client = new Typesense.Client({
  nodes: [
    {
      host: '127.0.0.1',
      port: '8108',
      protocol: 'http'
    }
  ],
  apiKey: 'qXVpO8JqTZHrT2IQ4rb2c7CT9SBOvmIv',
  connectionTimeoutSeconds: 2
});

async function run() {
  try {
    console.log("Deleting existing collection...");
    try {
      await client.collections('cities').delete();
    } catch (e) {
      console.log("Collection did not exist or could not be deleted.");
    }

    console.log("Creating collection...");
    await client.collections().create({
      name: 'cities',
      fields: [
        { name: 'name', type: 'string' },
        { name: 'country', type: 'string' },
        { name: 'population', type: 'int32' }
      ],
      default_sorting_field: 'population'
    });

    console.log("Collection created. Reading cities.json...");
    const cities = JSON.parse(fs.readFileSync('./data/cities.json', 'utf8'));
    console.log(`Loaded ${cities.length} cities. Importing...`);

    const result = await client.collections('cities').documents().import(cities, { action: 'create' });
    console.log("Import result sample:", JSON.stringify(result).substring(0, 200));

    console.log("Searching...");
    const searchResult = await client.collections('cities').documents().search({
      q: 'San',
      query_by: 'name',
      sort_by: 'population:desc,name:asc',
      per_page: 8
    });
    console.log("Search result hits count:", searchResult.hits.length);
    if (searchResult.hits.length > 0) {
      console.log("First hit highlight:", JSON.stringify(searchResult.hits[0].highlight));
    }
  } catch (err) {
    console.error("Error:", err);
  }
}

